return [
    'page_title' => 'ਨਿਯਮ ਅਤੇ ਸ਼ਰਤਾਂ',
    'last_updated' => 'ਆਖ਼ਰੀ ਅੱਪਡੇਟ :date',
    's1_title' => '1. ਇਹਨਾਂ ਨਿਯਮਾਂ ਨਾਲ ਸਹਿਮਤੀ।',
    's1_body' => 'ਇਹ ਨਿਯਮ ਅਤੇ ਸ਼ਰਤਾਂ ("ਨਿਯਮ") ਸਾਡੀ ਵੈੱਬਸਾਈਟ, ਮੋਬਾਈਲ ਅਨੁਭਵ ਅਤੇ ਸਾਰੀਆਂ ਸੰਬੰਧਿਤ ਖਾਤਾ, ਭੁਗਤਾਨ, ਕਾਰਡ ਅਤੇ ਸਹਾਇਤਾ ਸਹੂਲਤਾਂ (ਇਕੱਠੇ, "ਸੇਵਾ") ਸਮੇਤ Ledger ਤੱਕ ਤੁਹਾਡੀ ਪਹੁੰਚ ਅਤੇ ਵਰਤੋਂ ਨੂੰ ਨਿਯੰਤ੍ਰਿਤ ਕਰਦੇ ਹਨ। ਖਾਤਾ ਬਣਾ ਕੇ ਜਾਂ ਸੇਵਾ ਵਰਤ ਕੇ, ਤੁਸੀਂ ਇਹਨਾਂ ਨਿਯਮਾਂ ਅਤੇ ਇਹਨਾਂ ਵਿੱਚ ਹਵਾਲਾ ਦਿੱਤੀਆਂ ਨੀਤੀਆਂ ਦੇ ਪਾਬੰਦ ਹੋਣ ਲਈ ਸਹਿਮਤ ਹੁੰਦੇ ਹੋ। ਜੇ ਤੁਸੀਂ ਸਹਿਮਤ ਨਹੀਂ ਹੋ, ਤਾਂ ਖਾਤਾ ਨਾ ਬਣਾਓ ਅਤੇ ਸੇਵਾ ਨਾ ਵਰਤੋ।',
    's2_title' => '2. ਯੋਗਤਾ।',
    's2_body' => "Ledger ਖਾਤਾ ਖੋਲ੍ਹਣ ਅਤੇ ਰੱਖਣ ਲਈ ਤੁਹਾਡੀ ਉਮਰ ਘੱਟੋ-ਘੱਟ 18 ਸਾਲ ਹੋਣੀ ਚਾਹੀਦੀ ਹੈ, ਤੁਸੀਂ ਬੰਧਨਕਾਰੀ ਇਕਰਾਰਨਾਮਾ ਕਰਨ ਦੇ ਸਮਰੱਥ ਹੋਣੇ ਚਾਹੀਦੇ ਹੋ, ਅਤੇ ਮੰਗੇ ਜਾਣ 'ਤੇ ਸਰਕਾਰ ਵੱਲੋਂ ਜਾਰੀ ਵੈਧ ਪਛਾਣ ਦਸਤਾਵੇਜ਼ ਅਤੇ ਸਥਾਈ ਰਿਹਾਇਸ਼ੀ ਪਤਾ ਦੇ ਸਕਣੇ ਚਾਹੀਦੇ ਹੋ। ਜੇ ਅਸੀਂ ਤੁਹਾਡੀ ਪਛਾਣ ਦੀ ਪੁਸ਼ਟੀ ਨਾ ਕਰ ਸਕੀਏ, ਤੁਸੀਂ ਸਰਕਾਰੀ ਪਾਬੰਦੀ ਜਾਂ ਨਿਗਰਾਨੀ ਸੂਚੀ ਵਿੱਚ ਹੋਵੋ, ਜਾਂ ਖਾਤਾ ਖੋਲ੍ਹਣਾ ਜਾਂ ਰੱਖਣਾ Ledger ਨੂੰ ਕਾਨੂੰਨੀ ਜਾਂ ਰੈਗੂਲੇਟਰੀ ਜੋਖਮ ਵਿੱਚ ਪਾਵੇ, ਤਾਂ ਅਸੀਂ ਖਾਤਾ ਖੋਲ੍ਹਣ ਤੋਂ ਇਨਕਾਰ ਕਰ ਸਕਦੇ ਹਾਂ ਜਾਂ ਮੌਜੂਦਾ ਖਾਤਾ ਬੰਦ ਕਰ ਸਕਦੇ ਹਾਂ।",
    's3_title' => '3. ਤੁਹਾਡਾ ਖਾਤਾ।',
    's3_body' => 'Ledger ਖਾਤੇ ਦਾ ਬਕਾਇਆ Ledger ਬੈਂਕ ਵਜੋਂ ਸਿੱਧਾ ਨਹੀਂ ਰੱਖਦਾ। ਫੰਡ ਇੱਕ ਜਾਂ ਵੱਧ FDIC-ਬੀਮਾਕ੍ਰਿਤ ਭਾਈਵਾਲ ਬੈਂਕਾਂ ਵਿੱਚ ਸਾਂਝੇ ਕਸਟੋਡੀਅਲ ਖਾਤਿਆਂ ਵਿੱਚ ਰੱਖੇ ਜਾਂਦੇ ਹਨ, ਅਤੇ ਤੁਹਾਡੇ ਫੰਡ ਲਾਗੂ ਸੀਮਾ ਤੱਕ FDIC ਦੇ "ਪਾਸ-ਥਰੂ" ਜਮ੍ਹਾਂ ਬੀਮੇ ਦੇ ਯੋਗ ਹਨ; ਇਹ FDIC ਨਿਯਮਾਂ, ਉਸੇ ਭਾਈਵਾਲ ਬੈਂਕ ਵਿੱਚ ਤੁਹਾਡੇ ਹੋਰ ਫੰਡਾਂ ਨਾਲ ਜੋੜ ਅਤੇ ਭਾਈਵਾਲ ਬੈਂਕ ਦੀ ਅਸਫਲਤਾ ਦੇ ਅਧੀਨ ਹੈ। Ledger ਖ਼ੁਦ ਇੱਕ ਵਿੱਤੀ ਤਕਨਾਲੋਜੀ ਕੰਪਨੀ ਹੈ, ਲਾਇਸੈਂਸਸ਼ੁਦਾ ਬੈਂਕ ਨਹੀਂ। ਲਿਖਤੀ ਤੌਰ \'ਤੇ ਹੋਰ ਸਹਿਮਤੀ ਨਾ ਹੋਵੇ ਤਾਂ ਤੁਸੀਂ ਸਿਰਫ਼ ਇੱਕ ਨਿੱਜੀ ਖਾਤਾ ਰੱਖ ਸਕਦੇ ਹੋ, ਅਤੇ ਸਾਡੀ ਪਹਿਲਾਂ ਦੀ ਲਿਖਤੀ ਸਹਿਮਤੀ ਤੋਂ ਬਿਨਾਂ ਕਿਸੇ ਕਾਰੋਬਾਰ, ਟਰੱਸਟ ਜਾਂ ਹੋਰ ਵਿਅਕਤੀ ਵੱਲੋਂ ਫੰਡ ਪ੍ਰਾਪਤ ਕਰਨ ਲਈ ਖਾਤਾ ਨਹੀਂ ਵਰਤਿਆ ਜਾ ਸਕਦਾ।',
    's4_title' => '4. ਪਛਾਣ ਦੀ ਪੁਸ਼ਟੀ ਅਤੇ ਖਾਤਾ ਸੀਮਾਵਾਂ।',
    's4_body' => "ਸੰਘੀ ਕਾਨੂੰਨ ਵਿੱਤੀ ਸੇਵਾ ਪ੍ਰਦਾਤਾਵਾਂ ਨੂੰ ਖਾਤਾ ਖੋਲ੍ਹਣ ਵਾਲੇ ਹਰ ਵਿਅਕਤੀ ਦੀ ਪਛਾਣ ਕਰਨ ਵਾਲੀ ਜਾਣਕਾਰੀ ਪ੍ਰਾਪਤ ਕਰਨ, ਪੁਸ਼ਟੀ ਕਰਨ ਅਤੇ ਦਰਜ ਕਰਨ ਲਈ ਪਾਬੰਦ ਕਰਦਾ ਹੈ। ਅਸੀਂ ਤੁਹਾਨੂੰ ਫ਼ੋਟੋ ਪਛਾਣ ਦਸਤਾਵੇਜ਼, ਸੈਲਫ਼ੀ ਜਾਂ ਪਤੇ ਦਾ ਸਬੂਤ ਜਮ੍ਹਾਂ ਕਰਨ ਲਈ ਕਹਿ ਸਕਦੇ ਹਾਂ, ਅਤੇ ਉਸ ਜਾਣਕਾਰੀ ਦੀ ਸਮੀਖਿਆ ਤੇ ਮਨਜ਼ੂਰੀ ਤੱਕ ਟ੍ਰਾਂਸਫ਼ਰ ਰਕਮਾਂ, ਕਾਰਡ ਜਾਰੀ ਕਰਨ ਜਾਂ ਹੋਰ ਸਹੂਲਤਾਂ ਨੂੰ ਸੀਮਤ ਕਰ ਸਕਦੇ ਹਾਂ। ਅਸੀਂ ਸਮੇਂ-ਸਮੇਂ ਤੁਹਾਡੀ ਜਾਣਕਾਰੀ ਦੀ ਮੁੜ ਪੁਸ਼ਟੀ ਕਰ ਸਕਦੇ ਹਾਂ ਅਤੇ ਅੱਪਡੇਟ ਜਾਣਕਾਰੀ ਦੀ ਬੇਨਤੀ ਦਾ ਜਵਾਬ ਨਾ ਮਿਲਣ 'ਤੇ ਪ੍ਰਭਾਵਿਤ ਸਹੂਲਤਾਂ ਮੁਅੱਤਲ ਕਰ ਸਕਦੇ ਹਾਂ।",
    's5_title' => '5. ਟ੍ਰਾਂਸਫ਼ਰ ਅਤੇ ਭੁਗਤਾਨ।',
    's5_body' => "ਸੇਵਾ ਪੈਸੇ ਹਿਲਾਉਣ ਦੇ ਕਈ ਤਰੀਕਿਆਂ ਦਾ ਸਮਰਥਨ ਕਰਦੀ ਹੈ, ਹਰੇਕ ਲੈਣ-ਦੇਣ ਸਮੇਂ ਦਿਖਾਈਆਂ ਸੀਮਾਵਾਂ, ਕੱਟ-ਆਫ਼ ਸਮਿਆਂ ਅਤੇ ਸਮੀਖਿਆ ਦੇ ਅਧੀਨ ਹੈ: (ੳ) Ledger ਤੋਂ Ledger ਟ੍ਰਾਂਸਫ਼ਰ, Ledger ਖਾਤਿਆਂ ਵਿਚਕਾਰ ਤੁਰੰਤ ਭੇਜੇ ਜਾਂਦੇ ਹਨ; (ਅ) ਬਾਹਰੀ ਬੈਂਕ ਟ੍ਰਾਂਸਫ਼ਰ, ਉਸੇ ਦੇਸ਼ ਦੇ ਲਿੰਕ ਕੀਤੇ ਜਾਂ ਚੁਣੇ ਬੈਂਕ ਨੂੰ ਉਸ ਬੈਂਕ ਦੀ ਰੂਟਿੰਗ ਜਾਣਕਾਰੀ ਨਾਲ ਭੇਜੇ ਜਾਂਦੇ ਹਨ; (ੲ) ਅੰਤਰਰਾਸ਼ਟਰੀ ਟ੍ਰਾਂਸਫ਼ਰ, ਤੁਹਾਡੇ ਦੇਸ਼ ਤੋਂ ਬਾਹਰਲੇ ਬੈਂਕ ਨੂੰ ਉਸਦੇ SWIFT/BIC ਕੋਡ ਅਤੇ ਖਾਤਾ ਜਾਂ IBAN ਨੰਬਰ ਨਾਲ ਭੇਜੇ ਜਾਂਦੇ ਹਨ, ਜੋ ਪਹੁੰਚਣ ਵਿੱਚ ਵੱਧ ਸਮਾਂ ਲੈ ਸਕਦੇ ਹਨ, ਸਾਡੇ ਕੰਟਰੋਲ ਤੋਂ ਬਾਹਰਲੇ ਵਿਚੋਲੇ ਬੈਂਕਾਂ ਰਾਹੀਂ ਜਾ ਸਕਦੇ ਹਨ, ਅਤੇ ਟ੍ਰਾਂਸਫ਼ਰ ਪ੍ਰੋਸੈਸ ਹੋਣ ਸਮੇਂ ਤੈਅ ਦਰ 'ਤੇ ਮੁਦਰਾ ਬਦਲਾਅ ਦੇ ਅਧੀਨ ਹੋ ਸਕਦੇ ਹਨ; (ਸ) ਬਿੱਲ ਭੁਗਤਾਨ, ਤੁਹਾਡੇ ਵੱਲੋਂ ਨਿਰਧਾਰਿਤ ਪ੍ਰਾਪਤਕਰਤਾ ਨੂੰ ਭੇਜਿਆ ਜਾਂਦਾ ਹੈ; ਅਤੇ (ਹ) ਕਢਵਾਉਣਾ ਅਤੇ ਟੌਪ-ਅੱਪ, ਜੋ ਤੁਹਾਡੇ Ledger ਬਕਾਏ ਅਤੇ ਲਿੰਕ ਕੀਤੇ ਕਾਰਡ ਜਾਂ ਬਾਹਰੀ ਖਾਤੇ ਵਿਚਕਾਰ ਪੈਸੇ ਹਿਲਾਉਂਦੇ ਹਨ। ਪ੍ਰਾਪਤਕਰਤਾ, ਰੂਟਿੰਗ, SWIFT/BIC ਅਤੇ ਖਾਤੇ ਦੇ ਵੇਰਵੇ ਪੂਰੇ ਅਤੇ ਸਹੀ ਦਰਜ ਕਰਨਾ ਤੁਹਾਡੀ ਜ਼ਿੰਮੇਵਾਰੀ ਹੈ — ਤੁਹਾਡੇ ਦਿੱਤੇ ਵੇਰਵਿਆਂ 'ਤੇ ਸਹੀ ਢੰਗ ਨਾਲ ਭੇਜਿਆ ਟ੍ਰਾਂਸਫ਼ਰ, ਭਾਵੇਂ ਉਹ ਵੇਰਵੇ ਗ਼ਲਤ ਹੋਣ, Ledger ਵਾਪਸ ਨਹੀਂ ਕਰ ਸਕਦਾ। ਸ਼ੱਕੀ ਧੋਖਾਧੜੀ, ਪਾਬੰਦੀ ਜਾਂਚ ਜਾਂ ਨਾਕਾਫ਼ੀ ਉਪਲਬਧ ਬਕਾਏ ਕਾਰਨ ਨਿਸ਼ਾਨਬੱਧ ਹੋਣ 'ਤੇ ਟ੍ਰਾਂਸਫ਼ਰ ਵਿੱਚ ਦੇਰੀ ਹੋ ਸਕਦੀ ਹੈ, ਇਸਨੂੰ ਸਮੀਖਿਆ ਲਈ ਰੋਕਿਆ ਜਾਂ ਰੱਦ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ।",
    's6_title' => '6. ਨਿਯਤ ਟ੍ਰਾਂਸਫ਼ਰ।',
    's6_body' => 'ਭਵਿੱਖ ਦੀ ਮਿਤੀ ਲਈ ਨਿਯਤ ਟ੍ਰਾਂਸਫ਼ਰ ਸਿਰਫ਼ ਚੁਣੀ ਮਿਤੀ ਨੂੰ ਹੀ ਜਮ੍ਹਾਂ ਹੁੰਦਾ ਹੈ ਅਤੇ ਅਸਲ ਵਿੱਚ ਤੁਹਾਡੇ ਬਕਾਏ ਵਿੱਚੋਂ ਨਿਕਲਣ ਤੱਕ ਗਾਰੰਟੀਸ਼ੁਦਾ ਨਹੀਂ ਹੈ। ਉਸ ਮਿਤੀ ਤੋਂ ਪਹਿਲਾਂ ਕਦੇ ਵੀ ਖਾਤੇ ਦੇ ਇਤਿਹਾਸ ਵਿੱਚੋਂ ਤੁਸੀਂ ਨਿਯਤ ਟ੍ਰਾਂਸਫ਼ਰ ਰੱਦ ਕਰ ਸਕਦੇ ਹੋ। ਜੇ ਨਿਯਤ ਮਿਤੀ ਨੂੰ ਉਪਲਬਧ ਬਕਾਇਆ ਨਾਕਾਫ਼ੀ ਹੋਵੇ, ਤਾਂ ਟ੍ਰਾਂਸਫ਼ਰ ਅਸਫਲ ਹੋ ਜਾਵੇਗਾ ਅਤੇ ਇਤਿਹਾਸ ਵਿੱਚ ਉਸੇ ਅਨੁਸਾਰ ਨਿਸ਼ਾਨਬੱਧ ਹੋਵੇਗਾ; ਲੋੜੀਂਦੇ ਫੰਡ ਉਪਲਬਧ ਹੋਣਾ ਯਕੀਨੀ ਬਣਾਉਣਾ ਤੁਹਾਡੀ ਜ਼ਿੰਮੇਵਾਰੀ ਹੈ।',
    's7_title' => '7. ਫ਼ੀਸਾਂ।',
    's7_body' => "ਸੇਵਾ ਰਾਹੀਂ ਸ਼ੁਰੂ ਕੀਤੇ Ledger ਤੋਂ Ledger ਟ੍ਰਾਂਸਫ਼ਰ, ਬਾਹਰੀ ਬੈਂਕ ਟ੍ਰਾਂਸਫ਼ਰ, ਅੰਤਰਰਾਸ਼ਟਰੀ ਟ੍ਰਾਂਸਫ਼ਰ, ਕਢਵਾਉਣ ਜਾਂ ਟੌਪ-ਅੱਪ ਲਈ Ledger ਇਸ ਵੇਲੇ ਕੋਈ ਫ਼ੀਸ ਨਹੀਂ ਲੈਂਦਾ। ਤੁਹਾਡਾ ਲਿੰਕ ਕੀਤਾ ਬੈਂਕ, ਕਾਰਡ ਜਾਰੀਕਰਤਾ ਜਾਂ ਪ੍ਰਾਪਤ ਕਰਨ ਵਾਲਾ ਅੰਤਰਰਾਸ਼ਟਰੀ ਬੈਂਕ ਫਿਰ ਵੀ ਆਪਣੀਆਂ ਫ਼ੀਸਾਂ ਲਗਾ ਸਕਦਾ ਹੈ — ਅੰਤਰਰਾਸ਼ਟਰੀ ਟ੍ਰਾਂਸਫ਼ਰ 'ਤੇ ਮੁਦਰਾ ਬਦਲਾਅ, ਵਾਇਰ ਜਾਂ ਵਿਚੋਲੇ ਬੈਂਕ ਦੀਆਂ ਫ਼ੀਸਾਂ ਸਮੇਤ — ਜੋ ਸਾਡੇ ਕੰਟਰੋਲ ਤੋਂ ਬਾਹਰ ਹਨ ਅਤੇ Ledger ਨਾ ਵਸੂਲਦਾ ਹੈ ਨਾ ਰੱਖਦਾ ਹੈ। ਜੇ ਭਵਿੱਖ ਵਿੱਚ Ledger ਕਿਸੇ ਸਹੂਲਤ ਲਈ ਫ਼ੀਸ ਸ਼ੁਰੂ ਕਰੇ, ਤਾਂ ਲੈਣ-ਦੇਣ ਦੀ ਪੁਸ਼ਟੀ ਤੋਂ ਪਹਿਲਾਂ ਤੁਹਾਨੂੰ ਦੱਸਿਆ ਜਾਵੇਗਾ, ਅਤੇ ਇਸਦਾ ਵਰਣਨ ਕਰਨ ਲਈ ਇਹ ਨਿਯਮ ਅੱਪਡੇਟ ਕੀਤੇ ਜਾਣਗੇ।",
    's8_title' => '8. ਕਾਰਡ।',
    's8_body' => 'ਜੇ ਤੁਸੀਂ ਆਪਣੇ Ledger ਬਕਾਏ ਨਾਲ ਲਿੰਕ ਵਰਚੁਅਲ ਜਾਂ ਭੌਤਿਕ ਡੈਬਿਟ ਕਾਰਡ ਦੀ ਬੇਨਤੀ ਕਰਦੇ ਹੋ, ਤਾਂ ਉਹ ਕਾਰਡ ਮਨਜ਼ੂਰੀ ਦੇ ਅਧੀਨ ਹੈ ਅਤੇ ਜਾਰੀ ਹੋਣ ਤੋਂ ਬਾਅਦ ਹਰ ਖਰੀਦ ਸਮੇਂ ਸਿੱਧਾ ਤੁਹਾਡੇ ਉਪਲਬਧ ਬਕਾਏ ਵਿੱਚੋਂ ਕੱਟਦਾ ਹੈ — ਇਹ ਕ੍ਰੈਡਿਟ ਲਾਈਨ ਨਹੀਂ ਹੈ। ਗੁੰਮ, ਚੋਰੀ ਜਾਂ ਖ਼ਤਰੇ ਵਿੱਚ ਪਏ ਕਾਰਡ ਨੂੰ ਫ੍ਰੀਜ਼ ਜਾਂ ਬੰਦ ਕਰਨ ਲਈ ਕਾਰਡ ਪੰਨੇ ਰਾਹੀਂ ਤੁਰੰਤ ਰਿਪੋਰਟ ਕਰਨਾ ਲਾਜ਼ਮੀ ਹੈ; ਰਿਪੋਰਟ ਮਿਲਣ ਤੋਂ ਪਹਿਲਾਂ ਹੋਏ ਲੈਣ-ਦੇਣ ਲਈ ਤੁਸੀਂ ਜ਼ਿੰਮੇਵਾਰ ਰਹਿੰਦੇ ਹੋ, ਸਿਵਾਏ ਜਿੱਥੇ ਲਾਗੂ ਕਾਨੂੰਨ ਅਤੇ ਹੇਠਾਂ ਧਾਰਾ 10 ਸੀਮਤ ਕਰਦੀ ਹੈ।',
    's9_title' => '9. ਤੁਹਾਡੀਆਂ ਜ਼ਿੰਮੇਵਾਰੀਆਂ ਅਤੇ ਖਾਤਾ ਸੁਰੱਖਿਆ।',
    's9_body' => 'ਆਪਣਾ ਪਾਸਵਰਡ, ਲੈਣ-ਦੇਣ PIN, ਦੋ-ਪੜਾਵੀ ਪ੍ਰਮਾਣਿਕਤਾ ਕੋਡ ਅਤੇ Ledger ਵਰਤਣ ਵਾਲਾ ਡਿਵਾਈਸ ਸੁਰੱਖਿਅਤ ਰੱਖਣਾ ਅਤੇ ਇਹਨਾਂ ਨੂੰ ਕਿਸੇ ਨਾਲ ਸਾਂਝਾ ਨਾ ਕਰਨਾ ਤੁਹਾਡੀ ਜ਼ਿੰਮੇਵਾਰੀ ਹੈ। ਜੇ ਤੁਹਾਨੂੰ ਲੱਗੇ ਕਿ ਤੁਹਾਡਾ ਖਾਤਾ, ਪਾਸਵਰਡ ਜਾਂ ਕਾਰਡ ਖ਼ਤਰੇ ਵਿੱਚ ਹੈ, ਜਾਂ ਕੋਈ ਅਣਪਛਾਤਾ ਲੈਣ-ਦੇਣ ਦਿਖੇ, ਤਾਂ ਸਹਾਇਤਾ ਪੰਨੇ ਰਾਹੀਂ ਤੁਰੰਤ ਸਾਨੂੰ ਸੂਚਿਤ ਕਰਨਾ ਲਾਜ਼ਮੀ ਹੈ। ਤੁਸੀਂ ਆਪਣੀ ਸੰਪਰਕ ਜਾਣਕਾਰੀ, ਡਾਕ ਪਤਾ ਅਤੇ ਰਿਕਾਰਡ ਵਿਚਲੇ ਪਛਾਣ ਦਸਤਾਵੇਜ਼ ਅੱਪਡੇਟ ਅਤੇ ਸਹੀ ਰੱਖਣ ਲਈ ਸਹਿਮਤ ਹੋ।',
    's10_title' => '10. ਗ਼ਲਤੀਆਂ ਅਤੇ ਅਣਅਧਿਕਾਰਤ ਲੈਣ-ਦੇਣ।',
    's10_body' => "ਜੇ ਤੁਹਾਨੂੰ ਲੱਗੇ ਕਿ ਕੋਈ ਟ੍ਰਾਂਸਫ਼ਰ, ਕਾਰਡ ਚਾਰਜ ਜਾਂ ਹੋਰ ਲੈਣ-ਦੇਣ ਤੁਹਾਡੀ ਇਜਾਜ਼ਤ ਤੋਂ ਬਿਨਾਂ ਹੋਇਆ, ਜਾਂ ਤੁਹਾਡੀ ਖਾਤਾ ਸਟੇਟਮੈਂਟ ਵਿੱਚ ਗ਼ਲਤੀ ਹੈ, ਤਾਂ ਜਿੰਨੀ ਜਲਦੀ ਹੋ ਸਕੇ ਅਤੇ ਗਤੀਵਿਧੀ ਇਤਿਹਾਸ ਵਿੱਚ ਪਹਿਲੀ ਵਾਰ ਦਿਖਾਈ ਦੇਣ ਤੋਂ 60 ਦਿਨਾਂ ਦੇ ਅੰਦਰ ਸਹਾਇਤਾ ਨਾਲ ਸੰਪਰਕ ਕਰੋ। ਅਸੀਂ ਨੇਕ ਨੀਅਤ ਨਾਲ ਜਾਂਚ ਕਰਾਂਗੇ ਅਤੇ ਜਾਂਚ ਚੱਲਦੇ ਸਮੇਂ ਆਰਜ਼ੀ ਤੌਰ 'ਤੇ ਫੰਡ ਵਾਪਸ ਕਰ ਸਕਦੇ ਹਾਂ। ਪੁਸ਼ਟੀ ਹੋਏ ਅਣਅਧਿਕਾਰਤ ਲੈਣ-ਦੇਣ ਲਈ ਤੁਹਾਡੀ ਦੇਣਦਾਰੀ ਲਾਗੂ ਕਾਨੂੰਨ ਦੀ ਲੋੜ ਅਨੁਸਾਰ ਸੀਮਤ ਹੈ, ਬਸ਼ਰਤੇ ਤੁਸੀਂ ਸਾਨੂੰ ਤੁਰੰਤ ਸੂਚਿਤ ਕਰੋ ਅਤੇ ਆਪਣੇ ਲੌਗਇਨ ਵੇਰਵਿਆਂ ਦੀ ਸੁਰੱਖਿਆ ਵਿੱਚ ਧੋਖਾਧੜੀ ਜਾਂ ਘੋਰ ਲਾਪਰਵਾਹੀ ਨਾ ਕੀਤੀ ਹੋਵੇ।",
    's11_title' => '11. ਵਰਜਿਤ ਵਰਤੋਂ।',
    's11_body' => "ਤੁਸੀਂ ਸਹਿਮਤ ਹੋ ਕਿ ਮਨੀ ਲਾਂਡਰਿੰਗ, ਅੱਤਵਾਦ ਲਈ ਫੰਡਿੰਗ, ਧੋਖਾਧੜੀ ਜਾਂ ਪਾਬੰਦੀਆਂ ਤੋਂ ਬਚਣ ਸਮੇਤ ਕਿਸੇ ਵੀ ਗ਼ੈਰ-ਕਾਨੂੰਨੀ ਮਕਸਦ ਲਈ ਸੇਵਾ ਨਹੀਂ ਵਰਤੋਗੇ; ਕਾਨੂੰਨੀ ਤੌਰ 'ਤੇ ਹੱਕਦਾਰ ਨਾ ਹੋਣ ਵਾਲੇ ਫੰਡ ਨਹੀਂ ਭੇਜੋਗੇ ਜਾਂ ਪ੍ਰਾਪਤ ਕਰੋਗੇ; ਕਿਸੇ ਹੋਰ ਵਰਤੋਂਕਾਰ ਦੇ ਖਾਤੇ ਜਾਂ Ledger ਦੇ ਸਿਸਟਮਾਂ ਤੱਕ ਅਣਅਧਿਕਾਰਤ ਪਹੁੰਚ ਦੀ ਕੋਸ਼ਿਸ਼ ਨਹੀਂ ਕਰੋਗੇ; ਅਤੇ ਸੇਵਾ ਦੇ ਆਮ ਕੰਮਕਾਜ ਵਿੱਚ ਦਖ਼ਲ ਨਹੀਂ ਦਿਓਗੇ। ਇਸ ਧਾਰਾ ਦੀ ਉਲੰਘਣਾ ਕਰਨ ਦਾ ਵਾਜਬ ਵਿਸ਼ਵਾਸ ਹੋਣ ਵਾਲੇ ਕਿਸੇ ਵੀ ਲੈਣ-ਦੇਣ ਨੂੰ ਅਸੀਂ ਰੱਦ, ਦੇਰੀ, ਸੰਭਵ ਹੋਵੇ ਤਾਂ ਵਾਪਸ ਜਾਂ ਰਿਪੋਰਟ ਕਰ ਸਕਦੇ ਹਾਂ, ਅਤੇ ਕਾਨੂੰਨ ਦੀ ਲੋੜ ਅਨੁਸਾਰ ਕਾਨੂੰਨ ਲਾਗੂ ਕਰਨ ਵਾਲੀਆਂ ਏਜੰਸੀਆਂ ਜਾਂ ਰੈਗੂਲੇਟਰਾਂ ਨਾਲ ਜਾਣਕਾਰੀ ਸਾਂਝੀ ਕਰ ਸਕਦੇ ਹਾਂ।",
    's12_title' => '12. ਖਾਤੇ ਦੀ ਸਥਿਤੀ, ਮੁਅੱਤਲੀ ਅਤੇ ਬੰਦ ਕਰਨਾ।',
    's12_body' => 'ਅਸੀਂ ਆਪਣੇ ਵਿਵੇਕ ਨਾਲ ਤੁਹਾਡਾ ਖਾਤਾ ਫ੍ਰੀਜ਼, ਸੀਮਤ, ਮੁਅੱਤਲ ਜਾਂ ਬੰਦ ਕਰ ਸਕਦੇ ਹਾਂ, ਜਾਂ ਕਿਸੇ ਖ਼ਾਸ ਲੈਣ-ਦੇਣ ਨੂੰ ਰੱਦ ਕਰ ਸਕਦੇ ਹਾਂ — ਕਾਨੂੰਨ ਦੀ ਪਾਲਣਾ, ਸ਼ੱਕੀ ਧੋਖਾਧੜੀ ਜਾਂ ਦੁਰਵਰਤੋਂ ਦੀ ਜਾਂਚ, ਕਾਨੂੰਨੀ ਜਾਂ ਰੈਗੂਲੇਟਰੀ ਬੇਨਤੀ ਦਾ ਜਵਾਬ ਦੇਣ ਲਈ, ਜਾਂ ਜਿੱਥੇ ਸਾਨੂੰ ਵਾਜਬ ਵਿਸ਼ਵਾਸ ਹੋਵੇ ਕਿ ਤੁਹਾਡੀ, ਕਿਸੇ ਹੋਰ ਵਰਤੋਂਕਾਰ ਦੀ ਜਾਂ Ledger ਦੀ ਸੁਰੱਖਿਆ ਲਈ ਇਹ ਜ਼ਰੂਰੀ ਹੈ, ਸਮੇਤ। ਜਿੱਥੇ ਸੰਭਵ ਹੋਵੇ, ਅਸੀਂ ਕਾਰਨ ਅਤੇ ਸਹਾਇਤਾ ਪੰਨੇ ਰਾਹੀਂ ਸਾਡੇ ਨਾਲ ਕਿਵੇਂ ਸੰਪਰਕ ਕਰਨਾ ਹੈ ਦੱਸਾਂਗੇ। ਜੇ ਤੁਹਾਡਾ ਬਕਾਇਆ ਸਿਫ਼ਰ ਹੈ ਜਾਂ ਕਢਵਾ ਲਿਆ ਗਿਆ ਹੈ ਅਤੇ ਕੋਈ ਖੁੱਲ੍ਹੀ ਜਾਂਚ ਜਾਂ ਬਕਾਇਆ ਲੈਣ-ਦੇਣ ਨਹੀਂ ਹੈ, ਤਾਂ ਸਹਾਇਤਾ ਨਾਲ ਸੰਪਰਕ ਕਰਕੇ ਤੁਸੀਂ ਕਦੇ ਵੀ ਖਾਤਾ ਬੰਦ ਕਰ ਸਕਦੇ ਹੋ।',
    's13_title' => '13. ਸੇਵਾ ਦੀ ਉਪਲਬਧਤਾ; ਅਸਵੀਕਾਰਨ।',
    's13_body' => 'ਅਸੀਂ ਸੇਵਾ ਨੂੰ ਉਪਲਬਧ ਅਤੇ ਸਹੀ ਰੱਖਣ ਲਈ ਕੰਮ ਕਰਦੇ ਹਾਂ, ਪਰ ਸੇਵਾ "ਜਿਵੇਂ ਹੈ" ਪ੍ਰਦਾਨ ਕੀਤੀ ਜਾਂਦੀ ਹੈ ਅਤੇ ਅਸੀਂ ਗਾਰੰਟੀ ਨਹੀਂ ਦਿੰਦੇ ਕਿ ਇਹ ਹਮੇਸ਼ਾ ਬਿਨਾਂ ਰੁਕਾਵਟ, ਗ਼ਲਤੀ-ਰਹਿਤ ਜਾਂ ਉਪਲਬਧ ਰਹੇਗੀ। ਭਾਈਵਾਲ ਬੈਂਕ, ਕਾਰਡ ਨੈੱਟਵਰਕ ਜਾਂ ਵਿਚੋਲੀ ਸੰਸਥਾ ਵਿੱਚ ਰੁਕਾਵਟਾਂ, ਜਾਂ ਕੁਦਰਤੀ ਆਫ਼ਤਾਂ ਸਮੇਤ ਸਾਡੇ ਵਾਜਬ ਕੰਟਰੋਲ ਤੋਂ ਬਾਹਰਲੇ ਹਾਲਾਤਾਂ ਕਾਰਨ ਹੋਈ ਦੇਰੀ ਜਾਂ ਅਸਫਲਤਾ ਲਈ ਅਸੀਂ ਜ਼ਿੰਮੇਵਾਰ ਨਹੀਂ ਹਾਂ। ਕਾਨੂੰਨ ਦੀ ਇਜਾਜ਼ਤ ਦੀ ਪੂਰੀ ਹੱਦ ਤੱਕ, ਸੇਵਾ ਦੀ ਵਰਤੋਂ ਤੋਂ ਪੈਦਾ ਹੋਣ ਵਾਲੇ ਕਿਸੇ ਵੀ ਦਾਅਵੇ ਲਈ Ledger ਦੀ ਕੁੱਲ ਦੇਣਦਾਰੀ ਉਸ ਦਾਅਵੇ ਦਾ ਕਾਰਨ ਬਣੇ ਲੈਣ-ਦੇਣ ਦੀ ਰਕਮ ਤੱਕ ਸੀਮਤ ਹੈ, ਸਿਵਾਏ ਜਿੱਥੇ ਖਪਤਕਾਰਾਂ ਦੇ ਵਿੱਤੀ ਖਾਤਿਆਂ ਦੀ ਸੁਰੱਖਿਆ ਕਰਨ ਵਾਲਾ ਕਾਨੂੰਨ ਵਿਆਪਕ ਉਪਾਅ ਦੀ ਮੰਗ ਕਰੇ।',
    's14_title' => '14. ਵਿਵਾਦ ਨਿਪਟਾਰਾ।',
    's14_body' => "ਜੇ ਤੁਹਾਡੇ ਅਤੇ Ledger ਵਿਚਕਾਰ ਮਤਭੇਦ ਹੋਵੇ, ਤਾਂ ਅਸੀਂ ਬੇਨਤੀ ਕਰਦੇ ਹਾਂ ਕਿ ਸਿੱਧਾ ਹੱਲ ਕਰਨ ਦੀ ਕੋਸ਼ਿਸ਼ ਲਈ ਪਹਿਲਾਂ ਸਹਾਇਤਾ ਨਾਲ ਸੰਪਰਕ ਕਰੋ — ਜ਼ਿਆਦਾਤਰ ਮਸਲੇ ਇਸੇ ਤਰ੍ਹਾਂ ਹੱਲ ਹੋ ਜਾਂਦੇ ਹਨ। ਜੇ ਵਿਵਾਦ ਗ਼ੈਰ-ਰਸਮੀ ਤੌਰ 'ਤੇ ਹੱਲ ਨਾ ਹੋਵੇ, ਤਾਂ ਕੋਈ ਵੀ ਧਿਰ ਲਾਗੂ ਕਾਨੂੰਨ ਅਧੀਨ ਉਪਲਬਧ ਕੋਈ ਵੀ ਉਪਾਅ ਲੈ ਸਕਦੀ ਹੈ। ਇਹਨਾਂ ਨਿਯਮਾਂ ਵਿੱਚ ਕੁਝ ਵੀ ਖਪਤਕਾਰ ਸੁਰੱਖਿਆ ਕਾਨੂੰਨ ਅਧੀਨ ਤੁਹਾਡੇ ਰਾਜ ਜਾਂ ਸੰਘੀ ਰੈਗੂਲੇਟਰ ਕੋਲ ਵਿਵਾਦ ਉਠਾਉਣ ਦੇ ਤੁਹਾਡੇ ਹੱਕ ਨੂੰ ਸੀਮਤ ਨਹੀਂ ਕਰਦਾ।",
    's15_title' => '15. ਗੋਪਨੀਯਤਾ।',
    's15_body' => "ਅਸੀਂ ਤੁਹਾਡੀ ਨਿੱਜੀ ਅਤੇ ਵਿੱਤੀ ਜਾਣਕਾਰੀ ਨੂੰ ਕਿਵੇਂ ਸੰਭਾਲਦੇ ਹਾਂ — ਅਸੀਂ ਕੀ ਇਕੱਠਾ ਕਰਦੇ ਹਾਂ, ਇਸਨੂੰ ਕਿਵੇਂ ਵਰਤਦੇ ਹਾਂ, ਕਿਸ ਨਾਲ ਸਾਂਝਾ ਕਰ ਸਕਦੇ ਹਾਂ (ਜਿਵੇਂ ਭਾਈਵਾਲ ਬੈਂਕ, ਪਛਾਣ ਪੁਸ਼ਟੀ ਪ੍ਰਦਾਤਾ ਅਤੇ ਸੇਵਾ ਚਲਾਉਣ ਲਈ ਲੋੜੀਂਦੇ ਕਾਰਡ ਨੈੱਟਵਰਕ), ਅਤੇ ਤੁਹਾਡੇ ਕੋਲ ਕਿਹੜੇ ਵਿਕਲਪ ਹਨ — ਇਹ ਸਾਡੇ ਗੋਪਨੀਯਤਾ ਅਭਿਆਸਾਂ ਵਿੱਚ ਦੱਸਿਆ ਗਿਆ ਹੈ। ਅਸੀਂ ਤੁਹਾਡੀ ਪਛਾਣ ਅਤੇ ਖਾਤਾ ਜਾਣਕਾਰੀ ਸਿਰਫ਼ ਸੇਵਾ ਚਲਾਉਣ, ਸੁਰੱਖਿਅਤ ਕਰਨ ਅਤੇ ਇਸ 'ਤੇ ਲਾਗੂ ਕਾਨੂੰਨ ਦੀ ਪਾਲਣਾ ਲਈ ਵਰਤਦੇ ਹਾਂ, ਅਤੇ ਤੁਹਾਡੀ ਨਿੱਜੀ ਜਾਣਕਾਰੀ ਨਹੀਂ ਵੇਚਦੇ।",
    's16_title' => '16. ਇਹਨਾਂ ਨਿਯਮਾਂ ਵਿੱਚ ਤਬਦੀਲੀਆਂ।',
    's16_body' => 'ਸੇਵਾ, ਸਾਡੇ ਭਾਈਵਾਲ ਬੈਂਕਾਂ ਜਾਂ ਲਾਗੂ ਕਾਨੂੰਨ ਵਿੱਚ ਤਬਦੀਲੀਆਂ ਨੂੰ ਦਰਸਾਉਣ ਲਈ ਅਸੀਂ ਸਮੇਂ-ਸਮੇਂ ਇਹ ਨਿਯਮ ਅੱਪਡੇਟ ਕਰ ਸਕਦੇ ਹਾਂ। ਮਹੱਤਵਪੂਰਨ ਤਬਦੀਲੀ ਕਰਨ \'ਤੇ ਅਸੀਂ ਉੱਪਰ "ਆਖ਼ਰੀ ਅੱਪਡੇਟ" ਮਿਤੀ ਅੱਪਡੇਟ ਕਰਾਂਗੇ ਅਤੇ ਜਿੱਥੇ ਕਾਨੂੰਨ ਮੰਗੇ, ਵਾਧੂ ਨੋਟਿਸ ਦੇਵਾਂਗੇ। ਤਬਦੀਲੀ ਲਾਗੂ ਹੋਣ ਤੋਂ ਬਾਅਦ ਸੇਵਾ ਵਰਤਦੇ ਰਹਿਣ ਦਾ ਮਤਲਬ ਹੈ ਕਿ ਤੁਸੀਂ ਅੱਪਡੇਟ ਨਿਯਮ ਸਵੀਕਾਰ ਕਰਦੇ ਹੋ; ਜੇ ਤੁਸੀਂ ਤਬਦੀਲੀ ਨਾਲ ਸਹਿਮਤ ਨਹੀਂ, ਤਾਂ ਸੇਵਾ ਵਰਤਣੀ ਬੰਦ ਕਰਕੇ ਖਾਤਾ ਬੰਦ ਕਰ ਦੇਣਾ ਚਾਹੀਦਾ ਹੈ।',
    's17_title' => '17. ਲਾਗੂ ਕਾਨੂੰਨ।',
    's17_body' => 'ਕਾਨੂੰਨਾਂ ਦੇ ਟਕਰਾਅ ਦੇ ਸਿਧਾਂਤਾਂ ਦੀ ਪਰਵਾਹ ਕੀਤੇ ਬਿਨਾਂ, ਇਹ ਨਿਯਮ ਸੰਯੁਕਤ ਰਾਜ ਅਮਰੀਕਾ ਅਤੇ ਉਸ ਰਾਜ ਦੇ ਕਾਨੂੰਨਾਂ ਦੁਆਰਾ ਨਿਯੰਤ੍ਰਿਤ ਹਨ ਜਿੱਥੇ Ledger ਦੇ ਕੰਮਕਾਜ ਦਾ ਮੁੱਖ ਦਫ਼ਤਰ ਹੈ, ਸਿਵਾਏ ਜਿੱਥੇ ਤੁਹਾਡੇ ਨਿਵਾਸ ਵਾਲਾ ਅਧਿਕਾਰ ਖੇਤਰ ਵੱਖਰਾ ਕਾਨੂੰਨ ਲਾਗੂ ਕਰਨ ਦੀ ਮੰਗ ਕਰੇ।',
    's18_title' => '18. ਸਾਡੇ ਨਾਲ ਸੰਪਰਕ ਕਰੋ।',
    's18_body' => 'ਇਹਨਾਂ ਨਿਯਮਾਂ, ਤੁਹਾਡੇ ਖਾਤੇ ਜਾਂ ਕਿਸੇ ਖ਼ਾਸ ਲੈਣ-ਦੇਣ ਬਾਰੇ ਸਵਾਲ :support_link ਪੰਨੇ ਰਾਹੀਂ ਕਦੇ ਵੀ ਭੇਜੇ ਜਾ ਸਕਦੇ ਹਨ।',
    'support_link_text' => 'ਸਹਾਇਤਾ',
];
